css:
figure{position:relative}
.tag{position:absolute; right:0; bottom:0;      /* insetは必ず0。角に密着 */
  margin:0; border-radius:0;                     /* 角丸を消すのが肝 */
  background:#E60012; color:#fff;
  font-size:10px; font-weight:700; letter-spacing:.08em; padding:3px 8px}

/* 写真と本文の境目にまたがせつつ左辺に密着させる版 */
.tag--seam{left:0; right:auto; bottom:-10px}

/* 対角にもう1点（順位プレート） */
.rank{position:absolute; left:0; bottom:-8px; width:30px;
  padding:4px 0 6px; text-align:center; color:#fff;
  background:linear-gradient(#D8B12E,#B8912A)}
.rank b{display:block; font-size:26px; line-height:.9}
